/* v49: dùng chung cho nhóm (GRP) và quy trình (EP.tgt) — quy trình được để trống */
function epCurHTML(k){ return k?gIconHTML(k):'<span class="ep-none" aria-hidden="true"></span>' }
function epCurName(k){ return k?epName(k):tx('Chưa chọn','None') }
function epShow(k){
  var c=document.getElementById('epCur'), n=document.getElementById('epCurN');
  if(c) c.innerHTML=epCurHTML(k); if(n) n.textContent=epCurName(k);
}
function epPickChar(c){
  EP.rec=[c].concat(EP.rec.filter(function(x){return x!==c})).slice(0,24); epSave();
  var T=EP.tgt||GRP; T.ic='e:'+c; T.err=''; epShow(T.ic);
  var q=document.getElementById('epQ'); if(q) q.value=''; EP.q=''; epClose(true);
}
function epClick(e){ var b=e.target.closest&&e.target.closest('.ep-e'); if(b) epPickChar(b.getAttribute('data-c')) }
function epDefault(){ var T=EP.tgt||GRP; T.ic=EP.tgt?'':'folder'; epShow(T.ic); var q=document.getElementById('epQ'); if(q) q.value=''; EP.q=''; epClose(false) }
/* bàn phím: Enter chọn kết quả đầu · ↓ vào danh sách kết quả · mũi tên di chuyển · Esc đóng (không đóng cả khung) */
function epKey(e){
  var a=document.activeElement, body=document.getElementById('epBody');
  if(e.key==='Escape'){ if(EP.open){ e.stopPropagation(); e.preventDefault(); epClose(true) } return }
  if(!body) return;
  var all=Array.prototype.slice.call(body.querySelectorAll('.ep-e'));
  if(a&&a.id==='epQ'){
    if(e.key==='Enter'){ e.preventDefault(); if(all[0]) epPickChar(all[0].getAttribute('data-c')); return }
    if(e.key==='ArrowDown'&&all[0]){ e.preventDefault(); all[0].focus() }
    return;
  }
  var ar={ArrowDown:1,ArrowUp:1,ArrowLeft:1,ArrowRight:1}; if(!ar[e.key]||!a||!a.classList.contains('ep-e')) return;
  e.preventDefault();
  var i=all.indexOf(a), nx=null;
  if(e.key==='ArrowRight') nx=all[i+1]; else if(e.key==='ArrowLeft') nx=all[i-1];
  else {
    var r=a.getBoundingClientRect(), cx=r.left+r.width/2, cy=r.top+r.height/2, best=1e9, dir=e.key==='ArrowDown'?1:-1;
    all.forEach(function(b){
      var q=b.getBoundingClientRect(), dy=(q.top+q.height/2-cy)*dir; if(dy<r.height/2) return;
      var d=dy*4+Math.abs(q.left+q.width/2-cx); if(d<best){ best=d; nx=b }
    });
    if(!nx&&dir<0){ var s=document.getElementById('epQ'); if(s) s.focus(); return }
  }
  if(nx){ nx.focus(); nx.scrollIntoView({block:'nearest'}) }
}
document.addEventListener('mousedown',function(e){
  if(!EP.open) return; var w=document.getElementById('epWrap');
  if(w && !w.contains(e.target)) epClose(false);
});


var EP_SUG='👥💰⏰📅🗓️🎧🎓🧾✈️🙋🏢💻📦🏆⚖️🛡️💼🧑‍💼🤝🏥🏖️🎂📝📋🗂️📁📄✅📊📈🧮⚙️🔒🔑🔔📢✉️📱🚚🚗🏠🌐🔧📚☕🎁🎯⭐🚩❤️👶🏦🔄';
var EP_TABS=[
  ['sg','⭐',['Gợi ý cho công việc','Suggested for work']],
  ['rc','🕘',['Dùng gần đây','Recently used']],
  ['0','😀',['Mặt cười & cảm xúc','Smileys & emotion']],
  ['1','👋',['Con người','People']],
  ['3','🐻',['Động vật & thiên nhiên','Animals & nature']],
  ['4','🍔',['Ăn uống','Food & drink']],
  ['5','✈️',['Du lịch & địa điểm','Travel & places']],
  ['6','⚽',['Hoạt động','Activities']],
  ['7','💡',['Đồ vật','Objects']],
  ['8','🔣',['Ký hiệu','Symbols']],
  ['9','🚩',['Cờ','Flags']]
];
EP.tab='sg'; EP.view=[];
function epTabName(t){ return LANG==='en'?t[2][1]:t[2][0] }
function epSugItems(){
  epItems(); var out=[], seen={};
  (EP_SUG.match(/(?:\p{Extended_Pictographic}️?(?:‍\p{Extended_Pictographic}️?)*)/gu)||[]).forEach(function(c){
    var it=EP.byChar[c]||EP.byChar[c.replace(/️/g,'')]; if(it&&!seen[it.c]){ seen[it.c]=1; out.push(it) }
  });
  return out;
}
function epSelChar(){ var T=EP.tgt||GRP; return T&&T.ic&&T.ic.indexOf('e:')===0?T.ic.slice(2):'' }
function epBtn(it,raw){
  var c=raw||epChar(it), lb=esc(epLabel(it)), on=epSelChar()===c;
  return '<button type="button" class="ep-e'+(on?' on':'')+'" role="option" aria-selected="'+on+'" data-c="'+c+'" title="'+lb+'" aria-label="'+lb+'">'+c+'</button>';
}
function epTabsHTML(){
  return EP_TABS.filter(function(t){ return t[0]!=='rc'||EP.rec.length }).map(function(t){
    var on=EP.tab===t[0], n=esc(epTabName(t));
    return '<button type="button" class="ep-tb'+(on?' on':'')+'" role="tab" aria-selected="'+on+'" data-t="'+t[0]+'" title="'+n+'" aria-label="'+n+'">'+t[1]+'</button>';
  }).join('');
}
function epBrowseHTML(){
  epItems();
  if(EP.tab==='rc'&&!EP.rec.length) EP.tab='sg';
  var t=EP_TABS.filter(function(x){return x[0]===EP.tab})[0], list, html='';
  if(EP.tab==='sg'){ list=epSugItems(); EP.view=list; html=list.map(function(it){return epBtn(it)}).join('') }
  else if(EP.tab==='rc'){
    list=[]; html=EP.rec.map(function(c){ var it=EP.byChar[c]; if(!it) return ''; list.push(it); return epBtn(it,c) }).join(''); EP.view=list;
  } else { list=epItems().filter(function(it){return String(it.g)===EP.tab}); EP.view=list; html=list.map(function(it){return epBtn(it)}).join('') }
  return '<div class="ep-cnt">'+esc(epTabName(t))+' <span>· '+list.length+'</span></div><div class="ep-grid" role="listbox">'+html+'</div>';
}
function epRender(){
  var pop=document.getElementById('epPop'), b=document.getElementById('epBody'), q=document.getElementById('epQ'), tb=document.getElementById('epTabs'); if(!pop||!b) return;
  if(!EP.open){ epClose(false); return }
  var s=EP.q.trim();
  if(s){ b.innerHTML=epBody(); EP.view=epFind(EP.q)||[]; if(tb) tb.hidden=true }
  else { if(tb){ tb.hidden=false; tb.innerHTML=epTabsHTML() } b.innerHTML=epBrowseHTML() }
  b.scrollTop=0; pop.hidden=false; if(q) q.setAttribute('aria-expanded','true');
  var tn=document.getElementById('epTone'); if(tn) tn.style.display=EP.view.some(function(it){return it.sk&&it.sk.length})?'':'none';
  var p=document.getElementById('epPrev'), n=document.getElementById('epPn');
  if(p) p.textContent=''; if(n) n.innerHTML='<b>'+(s?tx('Bấm để chọn · Enter chọn kết quả đầu','Click to pick · Enter picks the first result'):tx('Bấm một biểu tượng để chọn','Click an icon to pick it'))+'</b>';
  /* chiều cao danh sách theo chỗ còn trống trong ngăn → không làm ngăn phát sinh thanh cuộn ngoài */
  (function(){ var dr=pop.closest('.drw-b'); b.style.maxHeight='';
    if(dr){ var pr=pop.getBoundingClientRect(), dbr=dr.getBoundingClientRect(), head=(tb&&!tb.hidden?tb.offsetHeight:0)+(pop.querySelector('.ep-foot')||{offsetHeight:48}).offsetHeight;
      var avail=dbr.bottom-pr.top-head-8; b.style.maxHeight=Math.max(120,Math.min(248,avail))+'px' } })();
  var on=b.querySelector('.ep-e.on'); if(on&&!s){ var r=on.getBoundingClientRect(), br=b.getBoundingClientRect(); if(r.bottom>br.bottom||r.top<br.top) b.scrollTop=on.offsetTop-b.offsetTop-60 }
}
